      {"id": "harding-demsn", "institution": "harding", "credential": "demsn", "name": "Master's Entry into Professional Nursing (MEPN), MSN", "length": "5 semesters in 21 months (72 semester credit hours, 1,032 clinical hours)", "format": "On ground in Searcy with some hybrid online courses; clinicals in the Searcy and Little Rock regions", "prerequisites": [{"course": "General or College Chemistry", "code": null, "min_grade": "C"}, {"course": "Introductory Statistics", "code": null, "min_grade": "C"}, {"course": "Anatomy & Physiology I with lab", "code": null, "min_grade": "C"}, {"course": "Anatomy & Physiology II with lab", "code": null, "min_grade": "C"}, {"course": "Microbiology with lab", "code": null, "min_grade": "C"}, {"course": "General Psychology", "code": null, "min_grade": "C"}, {"course": "General Sociology", "code": null, "min_grade": "C"}, {"course": "Nutrition", "code": null, "min_grade": "C"}, {"course": "Lifespan Growth & Development", "code": null, "min_grade": "C"}, {"course": "College Writing", "code": null, "min_grade": "C"}, {"course": "Undergraduate Pathophysiology (strongly recommended)", "code": null, "min_grade": "C"}], "admission": {"entrance_exam": "HESI A2 (MAT or GRE optional)", "selection": "Application review; an interview may be required", "gpa": "3.2 cumulative undergraduate; 3.0 science GPA across the 4 science prerequisites (B or better preferred in science)", "deadline": null, "notes": "Apply through NursingCAS with transcripts, 3 references, a writing sample and a CV. Science prerequisites must be within the last 5 years. Also requires a background check, drug screen, current CPR and proof of a completed CNA course (certification not required). Traditional track: bachelor's degree in another field. Early Entry track: 87 undergraduate credit hours plus prerequisites. A combined BS Health Studies/MSN-MEPN track runs 5 years. No deadline is published (contact mepn@harding.edu)."}, "cost": {"amount": 79280, "basis": "Estimated total program cost as published: tuition $935/credit (from Fall 2026) + $40/credit technology fee + $8,000 clinical fees + $1,200 licensing prep + $200 graduation fee. Personal expenses are extra.", "year": "2026-27"}, "nclex_pass_rate": {"basis": "First-time NCLEX-RN pass rate, Arkansas State Board of Nursing 5-year licensure exam results (fiscal year July-June; all campuses of a college combined); 12 tested in 2025-26", "by_campus": {"All campuses": [{"year": "2025-26", "rate": 1.0, "tested": 12}, {"year": "2024-25", "rate": 1.0, "tested": 7}, {"year": "2023-24", "rate": 1.0, "tested": 11}]}, "source_url": "https://healthy.arkansas.gov/boards-commissions/boards/nursing-arkansas-state-board/education/nclex-exam/"}, "accreditation": "CCNE", "source_url": "https://www.harding.edu/nursing/hu-grad-mepn", "last_verified": "2026-11-23", "academic_year": "2026-27", "notes": "Prepares non-nurses for the NCLEX-RN. Sources conflict on state approval: the MEPN page says all Harding programs have continuing full ASBN approval, while another Harding page says the MEPN/EMEPN has initial ASBN approval. Check with the school. An earlier source set the Early Entry track at 90 credit hours; the current page says 87."},
      {"id": "harding-fnp", "institution": "harding", "credential": "fnp", "name": "Master of Science in Nursing - Family Nurse Practitioner (MSN-FNP)", "length": "5 continuous semesters full-time, 8 semesters part-time (7 for spring starts); 45 semester credit hours, 750 clinical practicum hours", "format": "Hybrid: weekly online coursework plus 3 required on-campus intensives a year (Searcy)", "prerequisites": [{"course": "Basic Inferential Statistics", "code": null, "min_grade": "C"}, {"course": "Health Assessment", "code": null, "min_grade": "C"}, {"course": "Nursing Research", "code": null, "min_grade": "C"}], "admission": {"entrance_exam": null, "selection": "Competitive; personal interview required", "gpa": "Undergraduate GPA of 3.0 or higher (conditional acceptance may be considered below 3.0)", "deadline": null, "notes": "Requires a BSN from an accredited nursing program at a regionally accredited institution and an unencumbered current compact or state RN license. Also requires legal U.S. residence, immunizations, a background check, a NursingCAS application and a $50 seat deposit after acceptance. TOEFL iBT 83+ (speaking 26+) applies to some applicants. Not available to residents of Louisiana, New York or North Carolina. No deadline is published (call 501-279-4859). The current page does not mention an RN work-experience requirement; an older catalog required 2,000 RN hours before practicum."}, "cost": {"amount": 51065, "basis": "Estimated degree total as published (tuition $9,150/semester full-time or $1,017/credit part-time, $40/credit tech fee up to $600, $4,500 clinical fees), plus a $200 graduation fee. Books and travel are extra.", "year": "2026-27"}, "nclex_pass_rate": {"basis": "Not applicable — graduate NP program for licensed RNs (certification exam, not NCLEX-RN)", "by_campus": null, "source_url": null}, "accreditation": "CCNE (Harding states its master's programs are CCNE-accredited)", "source_url": "https://www.harding.edu/nursing/graduate-programs/fnp/index", "last_verified": "2026-11-23", "academic_year": "2026-27", "notes": "The FNP page itself names no accreditor; the CCNE statement comes from https://www.harding.edu/nursing/hu-nursing.html and the MEPN page ('All nursing programs at Harding University are accredited by CCNE'). The 2022-23 catalog listed 720 clinical hours; the current page says 750.", "open_entry": true},
      {"id": "harding-rnbsn", "institution": "harding", "credential": "rnbsn", "name": "BSN individualized degree completion track for licensed nurses (formerly Advanced Placement Track)", "length": "Individualized full-time or part-time plan (no fixed length published)", "format": null, "prerequisites": [], "admission": {"entrance_exam": null, "selection": "Individual review of prior clinical and educational experience", "gpa": null, "deadline": null, "notes": "For people with a current unencumbered nursing license (RN or LPN) who do not hold a bachelor's degree. The completion plan is designed with the student. Older catalogs required work experience if the first nursing credential was earned 12+ months before admission. Contact nursing@harding.edu or the director of admissions at 501-279-4682."}, "cost": {"amount": 945, "basis": "Standard undergraduate tuition per credit hour, 2026-27. No track-specific rate is published.", "year": "2026-27"}, "nclex_pass_rate": {"basis": "Not applicable — degree completion track for already-licensed nurses", "by_campus": null, "source_url": null}, "accreditation": "CCNE (baccalaureate program)", "source_url": "https://www.harding.edu/nursing/undergraduate-program/", "last_verified": "2026-11-23", "academic_year": "2026-27", "notes": "This is not a standard online RN-to-BSN. It is an individualized track inside the BSN, and it also admits LPNs, who would finish with a pre-licensure BSN. Treat it as an RN-to-BSN option with caution and check with the school. The 2025-26 catalog excerpt found did not describe this track.", "open_entry": true},
      {"id": "jbu-bsn", "institution": "jbu", "credential": "bsn", "name": "Nursing, B.S.N.", "length": "4-year plan (122 credit hours); upper-division nursing cohort starts once a year in fall", "format": "In person, Siloam Springs; 240-hour senior capstone clinical internship", "prerequisites": [{"course": "Anatomy & Physiology I", "code": null, "min_grade": "B-"}, {"course": "Anatomy & Physiology II", "code": null, "min_grade": "B-"}], "admission": {"entrance_exam": "ATI TEAS required (2025-26 catalog); no minimum score published, and it is not the only factor", "selection": "Competitive when qualified applicants outnumber seats", "gpa": "2.8 on at least 58 credit hours of general education/core/nursing prerequisites; 2.5 combined science GPA in prerequisite sciences", "deadline": "March 1 nursing application; notification by April 15 (fall cohort)", "notes": "Two steps: admission to the university, then a separate application to upper-division nursing. Each NUR course needs a C or better. Graduation requires a portfolio and a standardized NCLEX-RN predictor exam. A 2022-23 guidebook said no entrance exam was required; the 2025-26 catalog says the TEAS is required. Check with the school."}, "cost": {"amount": 1057, "basis": "Tuition per credit hour for the BS Nursing degree (full-time status, 122 total hours), 2026-27. Full-time tuition + general fee is listed as $33,692/year. Course fees are extra.", "year": "2026-27"}, "nclex_pass_rate": {"basis": "First-time NCLEX-RN pass rate, Arkansas State Board of Nursing 5-year licensure exam results (fiscal year July-June; all campuses of a college combined); 18 tested in 2025-26. The board reports one figure for all of the school's BSN tracks", "by_campus": {"All campuses": [{"year": "2025-26", "rate": 0.8889, "tested": 18}, {"year": "2024-25", "rate": 0.913, "tested": 23}, {"year": "2023-24", "rate": 0.8, "tested": 30}]}, "source_url": "https://healthy.arkansas.gov/boards-commissions/boards/nursing-arkansas-state-board/education/nclex-exam/"}, "accreditation": "CCNE; full approval from the Arkansas State Board of Nursing", "source_url": "https://www.jbu.edu/majors/nursing/", "last_verified": "2026-11-23", "academic_year": "2026-27", "notes": "catalog.jbu.edu pages and the nursing guidebook PDF (https://catalog.jbu.edu/mime/media/30/1882/Nursing+Guidebook+Latest+Revision+7.24.24.pdf) returned 403 to automated reading. Admission details come from search excerpts of those JBU catalog/guidebook pages. Cost is from https://www.jbu.edu/financial-aid/on-campus-undergraduate/tuition-and-costs/. No RN-to-BSN, LPN bridge, accelerated or graduate nursing program was found on jbu.edu."},
      {"id": "ouachita-bsn", "institution": "ouachita", "credential": "bsn", "name": "Bachelor of Science in Nursing (BSN)", "length": "4-year residential program: 65-68 credit hours of core/prerequisites, then 60 credit hours of BSN courses over 4 semesters (fall start); 126-129 total hours", "format": "In person, Arkadelphia (100% face-to-face); clinicals across central and southern Arkansas", "prerequisites": [{"course": "College Algebra", "code": "MATH 1003", "min_grade": "C"}, {"course": "General Psychology", "code": "PSYC 1013", "min_grade": "C"}, {"course": "General Biology I", "code": "BIOL 1014", "min_grade": "C"}, {"course": "Contemporary World", "code": "CORE 1023", "min_grade": "C"}, {"course": "Fundamentals of Chemistry", "code": "CHEM 1024", "min_grade": "C"}, {"course": "Composition I", "code": "CORE 1043", "min_grade": "C"}, {"course": "Human Anatomy & Physiology I", "code": "BIOL 2014", "min_grade": "C"}, {"course": "Human Anatomy & Physiology II", "code": "BIOL 2024", "min_grade": "C"}, {"course": "Human Development or Nutrition", "code": "PSYC 2033 / DIET 3053", "min_grade": "C"}, {"course": "Applied Microbiology", "code": "BIOL 2604", "min_grade": "C"}, {"course": "Technical & Professional Writing", "code": "ENGL 3013", "min_grade": "C"}, {"course": "Health Care Pathophysiology (BSN pre-nursing course)", "code": "NSCI 3103", "min_grade": "C"}], "admission": {"entrance_exam": "ATI TEAS, 63% or above", "selection": "Competitive review: GPA in Nursing Curriculum Support Courses, courses completed at application, TEAS score, academic history", "gpa": "Overall Ouachita GPA of 2.5 or better at the end of the first semester of sophomore year (or transfer GPA 2.5+)", "deadline": null, "notes": "Applicants must be admitted to Ouachita and be declared nursing majors (transfer students need the Director of Nursing's approval). All 12 listed courses must be complete or in progress at application. Summer coursework makes acceptance contingent. TOEFL is required for some international applicants. BLS certification, a background check and a drug screen are required before clinicals. Students must keep a 2.0 GPA in nursing courses."}, "cost": {"amount": 18300, "basis": "Tuition per semester for 10-18 hours, 2026-27 (no out-of-state rate). General fee ($240) and technology fee ($140) per semester are extra, plus nursing course fees (e.g., $1,050 each for NURS 3006/4006 and NURS 3106/4206).", "year": "2026-27"}, "nclex_pass_rate": {"basis": "First-time NCLEX-RN pass rate, Arkansas State Board of Nursing 5-year licensure exam results (fiscal year July-June; all campuses of a college combined); 19 tested in 2025-26. The board reports one figure for all of the school's BSN tracks", "by_campus": {"All campuses": [{"year": "2025-26", "rate": 0.9474, "tested": 19}, {"year": "2024-25", "rate": 1.0, "tested": 20}, {"year": "2023-24", "rate": 0.92, "tested": 25}]}, "source_url": "https://healthy.arkansas.gov/boards-commissions/boards/nursing-arkansas-state-board/education/nclex-exam/"}, "accreditation": "ACEN (continuing accreditation); full approval from the Arkansas State Board of Nursing", "source_url": "https://obu.edu/academics/__Catalogs/Residential-Catalog/2026-27OuachitaResidentialCatalog.pdf", "last_verified": "2026-11-23", "academic_year": "2026-27", "notes": "The catalog's nursing section says ASBN 'Full Approval' and ACEN 'continuing accreditation' (ACEN renewal announced May 2026). The catalog's general accreditation section still says 'initially accredited' by ACEN and 'initially approved' by ASBN. The nursing section is newer and more specific; check with the school. No application deadline is published. obu.edu HTML pages returned 403; facts come from the 2026-27 residential catalog and 2025-26 degree sheet PDFs."},
      {"id": "philander-bsn", "institution": "philander", "credential": "bsn", "name": "Bachelor of Science in Nursing (BSN)", "length": "8 semesters / typically 4 years full-time (minimum 124 credit hours); nursing courses run in 8-week sessions (Fundamentals of Nursing is 16 weeks)", "format": null, "prerequisites": [], "admission": {"entrance_exam": "ATI TEAS, score of 65 or greater (plus ACT, SAT and/or Accuplacer Next Generation scores)", "selection": "Competitive; cohort size limited by clinical sites (HLC announcement: up to 50 students per year). An advisor reviews the application and the Director of Nursing grants final acceptance.", "gpa": "2.5 or greater on prerequisite nursing courses, each with a C or better", "deadline": "Third Friday in March before the desired academic year", "notes": "Requires a high school diploma or GED, all transcripts (via Parchment or the National Student Clearinghouse), nursing declared as major, TB test or chest x-ray, AHA healthcare provider CPR card, MMR and Tdap (within 10 years), and a background check and drug screen. Transfers from another nursing program need a Letter of Good Standing. Applicants may apply before finishing prerequisites. The site says no accelerated or RN-to-BSN track is offered."}, "cost": {"amount": null, "basis": "Not published for the current year. The only BSN fee schedule on the site is a 2024 file labeled 'Draft'.", "year": null}, "nclex_pass_rate": {"basis": "New program: no graduates appear in the Arkansas State Board of Nursing's NCLEX-RN results yet.", "by_campus": null, "source_url": null}, "accreditation": null, "source_url": "https://www.philander.edu/academics/school-of-allied-and-public-health/bsn/", "last_verified": "2026-11-23", "academic_year": "2026-27", "notes": "This is a new program. HLC approved the 124-credit BSN in May 2025 (news release, July 23, 2025). The program page says 'Now Accepting Applications for 2026-2027'; the admissions page says applications are open for Fall 2026. The site does not state ASBN approval status or any nursing accreditation or candidacy. Per the board, there are no graduates yet. The program also includes a nursing apprenticeship for PSU-trained CNAs. Prerequisite course list is in a curriculum PDF that was not reviewed."}
